import re

# Named rules — readability > regex cleverness.
RULES = [
    ('ignore-prior',     re.compile(r'\bignore\s+(?:all\s+)?previous\s+(?:instructions?|prompts?|messages?)\b', re.I)),
    ('disregard-above',  re.compile(r'\bdisregard\s+the\s+above\b', re.I)),
    ('reveal-prompt',    re.compile(r'\breveal\s+(?:your\s+)?(?:system\s+)?prompt\b', re.I)),
    ('forget-prior',     re.compile(r'\bforget\s+(?:what\s+i\s+said|the\s+above|prior(?:\s+messages?)?)\b', re.I)),
    ('system-prompt',    re.compile(r'\b(?:your\s+)?system\s+prompt\b', re.I)),
    ('role-rewrite',     re.compile(r'\byou\s+are\s+now\b|\bact\s+as\b', re.I)),
]

CODE_BLOCK = re.compile(r'```[\s\S]*?```')

def scan(user_input: str):
    if not isinstance(user_input, str):
        return { 'safe': False, 'reason': 'non-string input', 'matched_patterns': ['non-string-input'] }
    if len(user_input) == 0:
        return { 'safe': True, 'reason': None, 'matched_patterns': [] }

    # Strip code blocks before scanning — content inside ``` is whitelist.
    text = CODE_BLOCK.sub(' ', user_input)

    matched = []
    for name, rx in RULES:
        if rx.search(text):
            matched.append(name)

    if not matched:
        return { 'safe': True, 'reason': None, 'matched_patterns': [] }

    return {
        'safe': False,
        'reason': f"Matched {len(matched)} prompt-injection rule(s)",
        'matched_patterns': matched,
    }
